                            var rows = (ResultSet) returned;
                            return Proxy.newProxyInstance(
                                ResultSet.class.getClassLoader(),
                                new Class<?>[] {ResultSet.class},
                                (unused, read, values) -> {
                                  if (read.getName().equals("getObject")
