    for (boolean bodyFailed : List.of(false, true)) {
      for (Throwable secondary :
          List.of(
              new SQLException("PRIVATE_CLOSE"),
              new IllegalStateException("PRIVATE_CLOSE"),
              new AssertionError("PRIVATE_CLOSE"))) {
